INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 12, 'theory', 'HTTP/2 and HTTP/3: multiplexing and QUIC');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 12, 0, 'What does multiplexing in HTTP/2 give?', '["Encryption of all requests", "Many independent requests and responses over one connection, interleaving frames", "Automatic caching", "Replacing TCP with UDP"]', 1, 'Streams run in parallel over one connection: no need for six connections and a queue.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 12, 1, 'What is HPACK?', '["An encryption protocol", "A congestion control algorithm", "A method of compressing HTTP headers with a shared table", "A certificate format"]', 2, 'Repeated headers are sent as a reference to a table entry.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 12, 2, 'Why can HTTP/2 perform worse than HTTP/1.1 on a lossy network?', '["HTTP/2 cannot retransmit lost data", "HTTP/2 uses UDP", "HTTP/2 does not support caching", "Losing one TCP segment delays all streams on the shared connection"]', 3, 'TCP guarantees byte order, so a hole blocks the data of all streams.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 12, 3, 'Which transport does HTTP/3 use?', '["QUIC over UDP", "TCP", "SCTP", "ICMP"]', 0, 'QUIC implements reliability, streams and encryption on top of UDP.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 12, 4, 'A server advertises HTTP/3, but for clients behind a corporate firewall the page loads over HTTP/2. What is the most likely cause?', '["The certificate has expired", "TCP/80 is closed", "UDP/443 is closed on the firewall", "DNS is not working"]', 2, 'QUIC uses UDP/443; if it is closed, the browser falls back to TCP.');
